import React, { useEffect, useState } from "react";
import UsageGraph from "./UsageGraph";
import PokemonBuildPanel from "./";

const POKE_PATH = "/pokemon_data/";

export default function ComUsage() {
  const [pokemonList, setPokemonList] = useState([]);
  const [filteredList, setFilteredList] = useState([]);

  const [search, setSearch] = useState("");
  const [selectedPokemon, setSelectedPokemon] =
    useState(null);

  const [compareList, setCompareList] = useState([]);
  const [selectedGen, setSelectedGen] =
    useState("9");
  const [menuOpen, setMenuOpen] = useState(false);

  const [clickedBuild, setClickedBuild] =
    useState(null);

  const normalize = (str) =>
    str?.toLowerCase().replace(/[^a-z0-9]/g, "") ||
    "";

  const loadCSV = async (path) => {
    const res = await fetch(path);
    return await res.text();
  };

  const parseCSV = (text) =>
    text
      .trim()
      .split("\n")
      .slice(1)
      .map((r) =>
        r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
      );

  // Load Pokémon names
  useEffect(() => {
    const loadPokemonData = async () => {
      const text = await loadCSV(
        POKE_PATH + "pokemon_smogon_names.csv"
      );

      const rows = parseCSV(text);

      const list = rows.map((row) => ({
        display: row[0],
        smogon: row[1],
      }));

      setPokemonList(list);
      setFilteredList(list);
    };

    loadPokemonData();
  }, []);

  // Default selection
  useEffect(() => {
    if (!selectedPokemon && pokemonList.length > 0) {
      setSelectedPokemon(pokemonList[0]);
    }
  }, [pokemonList, selectedPokemon]);

  // Search filter
  useEffect(() => {
    const filtered = pokemonList.filter((p) =>
      normalize(p.display).includes(
        normalize(search)
      )
    );
    setFilteredList(filtered);
  }, [search, pokemonList]);

  // Fix invalid selection
  useEffect(() => {
    if (
      filteredList.length > 0 &&
      !filteredList.find(
        (p) =>
          p.display === selectedPokemon?.display
      )
    ) {
      setSelectedPokemon(filteredList[0]);
    }
  }, [filteredList, selectedPokemon]);

  // Reset clicked build when gen changes
  useEffect(() => {
    setClickedBuild(null);
  }, [selectedGen]);

  const addToCompare = () => {
    if (
      selectedPokemon &&
      !compareList.find(
        (p) =>
          p.display === selectedPokemon.display
      )
    ) {
      setCompareList([
        ...compareList,
        selectedPokemon,
      ]);
    }
  };

  const removeFromCompare = (name) => {
    setCompareList(
      compareList.filter((p) => p.display !== name)
    );
  };

  return (
    <div>
      <h2>Pokémon Usage Over Time</h2>

      <button
        onClick={() =>
          setMenuOpen(!menuOpen)
        }
      >
        ⚙️ Filters
      </button>

      <div
        style={{
          display: "flex",
          gap: "20px",
          alignItems: "flex-start",
          marginTop: "20px",
        }}
      >
        {/* Left Side: Filters + Graph */}
        <div style={{ flex: 1 }}>
          {menuOpen && (
            <div
              style={{
                background: "#f5f5f5",
                padding: "15px",
                marginBottom: "20px",
              }}
            >
              <label>Generation:</label>
              <select
                value={selectedGen}
                onChange={(e) =>
                  setSelectedGen(
                    e.target.value
                  )
                }
              >
                {[5, 6, 7, 8, 9].map((g) => (
                  <option
                    key={g}
                    value={g}
                  >
                    Gen {g}
                  </option>
                ))}
              </select>

              <br />
              <br />

              <input
                type="text"
                value={search}
                onChange={(e) =>
                  setSearch(
                    e.target.value
                  )
                }
                placeholder="Search Pokémon"
              />

              <br />
              <br />

              <select
                size="5"
                value={
                  selectedPokemon?.display ||
                  ""
                }
                onChange={(e) =>
                  setSelectedPokemon(
                    filteredList.find(
                      (p) =>
                        p.display ===
                        e.target.value
                    )
                  )
                }
              >
                {filteredList.map((p) => (
                  <option
                    key={p.display}
                  >
                    {p.display}
                  </option>
                ))}
              </select>

              <br />
              <br />

              <button
                onClick={addToCompare}
              >
                Add to Compare
              </button>

              <hr />

              {compareList.map((p) => (
                <div key={p.display}>
                  {p.display}
                  <button
                    onClick={() =>
                      removeFromCompare(
                        p.display
                      )
                    }
                  >
                    X
                  </button>
                </div>
              ))}
            </div>
          )}

          <UsageGraph
            compareList={compareList}
            selectedGen={selectedGen}
            onPointClick={setClickedBuild}
          />
        </div>

        {/* Right Side: Build Panel */}
        <div style={{ width: "400px" }}>
          <PokemonBuildPanel
            clickedBuild={clickedBuild}
            selectedGen={selectedGen}
          />
        </div>
      </div>
    </div>
  );
}
